#include "../source/cover_policy.h"
#include <cassert>
int main(){using namespace cover_policy;assert(valid(1024,1024));assert(!valid(0,1));assert(!valid(1025,1));assert(sidecar("sdmc:/roms","Game.sfc")=="sdmc:/roms/Game.png");assert(sidecar("x","Game.zip")=="x/Game.png");assert(scale(200,100,196,100)==0.98f);assert(scale(100,200,196,100)==0.5f);auto landscape=fit(400,200,300,300);assert(landscape.x==0&&landscape.y==75&&landscape.w==300&&landscape.h==150);auto portrait=fit(200,400,300,300);assert(portrait.x==75&&portrait.y==0&&portrait.w==150&&portrait.h==300);auto square=fit(100,100,300,200);assert(square.x==50&&square.y==0&&square.w==200&&square.h==200);assert(fit(0,100,300,200).w==0);Index i;i.add("Aladdin.png");i.add("Aladdin (USA).PNG");i.add("Super Mario World 2.png");assert(i.candidates("Aladdin (USA).sfc").front()=="Aladdin (USA).PNG");assert(i.candidates("ALADDIN (U) [!].zip").front()=="Aladdin.png");assert(i.candidates("Super Mario World.sfc").empty());assert(normalized("Aladdin (Rev 1) [!]")=="aladdin");assert(normalized("Game 2")!=normalized("Game"));Index a;a.add("Game (USA).png");a.add("Game (Japan).png");assert(a.candidates("Game (Europe).sfc").empty());Index j;j.add("Game.JPG");j.add("Game.jpeg");j.add("Game.png");assert(j.candidates("Game.sfc").size()==3);assert(j.candidates("Game.sfc").front()=="Game.png");assert(j.candidates("Game (USA).sfc").size()==3);Index slug;for(auto n:{"2020_super_baseball_usa.jpg","3_ninjas_kick_back_usa.jpg","7th_saga_the_usa.jpg","actraiser_usa.jpg","actraiser_2_usa.jpg","actraiser_japan.jpg","90_minutes_-_european_prime_goal_europe.jpg"})slug.add(n);assert(slug.candidates("2020 Super Baseball (U).sfc").front()=="2020_super_baseball_usa.jpg");assert(slug.candidates("3 Ninjas Kick Back (USA).sfc").front()=="3_ninjas_kick_back_usa.jpg");assert(slug.candidates("The 7th Saga (U).sfc").front()=="7th_saga_the_usa.jpg");assert(slug.candidates("ActRaiser (U) [!].sfc").front()=="actraiser_usa.jpg");assert(slug.candidates("ActRaiser 2 (U).sfc").front()=="actraiser_2_usa.jpg");assert(slug.candidates("ActRaiser (J).sfc").front()=="actraiser_japan.jpg");assert(slug.candidates("ActRaiser 3 (U).sfc").empty());assert(slug.candidates("90 Minutes - European Prime Goal (E).sfc").front()=="90_minutes_-_european_prime_goal_europe.jpg");Index nested;nested.add("boxart/Game.jpg");assert(nested.candidates("Game (USA, Europe).sfc").front()=="boxart/Game.jpg");Index more;more.add("battletoads_&_double_dragon_usa.jpg");more.add("american_tail_an_-_fievel_goes_west_usa.jpg");more.add("ballz_3d_-_fighting_at_its_ballziest_usa.jpg");more.add("asterix_europe.jpg");assert(!more.candidates("Battletoads and Double Dragon (U).sfc").empty());assert(!more.candidates("An American Tail - Fievel Goes West (U).sfc").empty());assert(!more.candidates("Ballz 3D (U).sfc").empty());assert(!more.candidates("Asterix (U).sfc").empty());assert(more.candidates("Asterix 2 (U).sfc").empty());}
